CREATE TABLE billing_rule (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, agreement_id BIGINT NOT NULL, agreement_item_id BIGINT NULL, rule_version INT NOT NULL, charge_type VARCHAR(32) NOT NULL, calculation_type VARCHAR(32) NOT NULL, billing_cycle_months INT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, unit_price DECIMAL(20,8) NOT NULL, quantity DECIMAL(20,6) NOT NULL DEFAULT 1, proration_method VARCHAR(32) NOT NULL DEFAULT 'NONE', free_days INT NOT NULL DEFAULT 0, escalation_type VARCHAR(32) NOT NULL DEFAULT 'NONE', escalation_value DECIMAL(20,8) NULL, due_rule_type VARCHAR(32) NOT NULL, due_rule_value INT NULL, priority INT NOT NULL DEFAULT 100, status VARCHAR(32) NOT NULL, calculation_config JSON NULL, UNIQUE KEY uk_bill_rule_ver(tenant_id,agreement_id,id,rule_version), KEY idx_bill_rule_ag(tenant_id,agreement_id,status));
CREATE TABLE billing_plan (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, agreement_id BIGINT NOT NULL, plan_version INT NOT NULL, status VARCHAR(32) NOT NULL, generated_at DATETIME(3) NOT NULL, UNIQUE KEY uk_plan_ver(tenant_id,agreement_id,plan_version));
CREATE TABLE billing_plan_item (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, billing_plan_id BIGINT NOT NULL, source_rule_id BIGINT NOT NULL, charge_type VARCHAR(32) NOT NULL, period_start DATETIME(3) NOT NULL, period_end DATETIME(3) NOT NULL, due_date DATE NOT NULL, planned_amount DECIMAL(18,2) NOT NULL, calculation_trace JSON NOT NULL, KEY idx_plan_item_due(tenant_id,due_date));
CREATE TABLE bill (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, bill_no VARCHAR(64) NOT NULL, agreement_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, period_start DATETIME(3) NOT NULL, period_end DATETIME(3) NOT NULL, original_amount DECIMAL(18,2) NOT NULL, adjustment_amount DECIMAL(18,2) NOT NULL DEFAULT 0, payable_amount DECIMAL(18,2) NOT NULL, due_date DATE NOT NULL, status VARCHAR(32) NOT NULL, issued_at DATETIME(3) NULL, version INT NOT NULL DEFAULT 0, UNIQUE KEY uk_bill(tenant_id,bill_no), KEY idx_bill_ag(tenant_id,agreement_id,status), KEY idx_bill_due(tenant_id,status,due_date));
CREATE TABLE bill_item (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, bill_id BIGINT NOT NULL, charge_type VARCHAR(32) NOT NULL, description VARCHAR(512) NULL, quantity DECIMAL(20,6) NOT NULL, unit_price DECIMAL(20,8) NOT NULL, original_amount DECIMAL(18,2) NOT NULL, discount_amount DECIMAL(18,2) NOT NULL DEFAULT 0, final_amount DECIMAL(18,2) NOT NULL, source_rule_id BIGINT NOT NULL, calculation_trace JSON NOT NULL, KEY idx_bill_item_bill(tenant_id,bill_id));
